# ссылка в самом конце текста новости («Ссылка на первоисточник: https://…») -> source_url
TAIL_URL = re.compile(r"(https?://[^\s<>\"']+?)[\s.)]*$")


def fill_source_url(apps, schema_editor):
    News = apps.get_model('main_app', 'News')
    for news in News.objects.all():
        text = re.sub(r"<[^>]+>", " ", news.body or "").strip()
        m = TAIL_URL.search(text)
        if m and not news.source_url:
            news.source_url = m.group(1)[:500]
            news.save(update_fields=['source_url'])


